const popup = document.querySelector('[data-brunito-welcome-popup]');
const reopen = document.querySelector('[data-welcome-reopen]');

if (popup && reopen) {
  const sessionKey = 'brunito-welcome-popup-closed';
  const subscribedKey = 'brunito-welcome-popup-subscribed';
  const read = (storage, key) => {
    try {
      return storage.getItem(key);
    } catch {
      return null;
    }
  };
  const write = (storage, key) => {
    try {
      storage.setItem(key, 'true');
    } catch {}
  };
  const subscribed = Boolean(popup.querySelector('[data-welcome-subscribed]'));
  const setReopenVisibility = (visible) => {
    reopen.hidden = !visible;
  };
  const close = () => popup.close();

  if (subscribed) {
    write(localStorage, subscribedKey);
    setReopenVisibility(false);
  } else if (read(localStorage, subscribedKey)) {
    setReopenVisibility(false);
  } else if (read(sessionStorage, sessionKey)) {
    setReopenVisibility(true);
  }

  const openFromReopen = () => {
    if (subscribed || popup.open || document.querySelector('dialog[open]:not([data-brunito-welcome-popup])')) return;

    setReopenVisibility(false);
    try {
      popup.showModal();
    } catch {
      setReopenVisibility(true);
    }
  };

  popup.querySelectorAll('[data-welcome-close]').forEach((control) => {
    control.addEventListener('click', close);
  });
  popup.addEventListener('click', (event) => {
    if (event.target === popup) close();
  });
  popup.addEventListener('close', () => {
    if (!subscribed) {
      write(sessionStorage, sessionKey);
      setReopenVisibility(true);
    }
  });
  reopen.addEventListener('click', openFromReopen);

  if (subscribed) {
    window.setTimeout(() => {
      if (!popup.open) popup.showModal();
    }, 250);
  } else if (!read(localStorage, subscribedKey) && !read(sessionStorage, sessionKey)) {
    window.setTimeout(() => {
      if (document.visibilityState === 'visible' && !document.querySelector('dialog[open]')) popup.showModal();
    }, Number(popup.dataset.delay || 6500));
  }
}
